const parts = [{"name": "Noun — பெயர்ச்சொல்", "def": "நபர், இடம், பொருள், உயிரினம், கருத்து அல்லது உணர்வின் பெயரைச் சொல்வது.", "ex": ["person: teacher, student", "place: school, Sri Lanka", "thing: book, phone", "idea/quality: honesty, happiness"], "note": "Types: Common (city), Proper (Colombo), Collective (team), Abstract (honesty), Concrete (table), Countable (book/books), Uncountable (water)."}, {"name": "Pronoun — பதிலிப்பெயர்", "def": "Noun-ஐ மீண்டும் மீண்டும் பயன்படுத்தாமல் அதற்குப் பதிலாக வரும் சொல்.", "ex": ["I, you, he, she, it, we, they", "me, him, her, us, them", "my, your, his, her, our, their"], "note": "Subject pronoun மற்றும் object pronoun-ஐ குழப்பக்கூடாது: She called me. (She = subject; me = object)."}, {"name": "Verb — வினைச்சொல்", "def": "செயல், நிகழ்வு அல்லது நிலையைச் சொல்வது.", "ex": ["action: run, write, study", "state: know, like, believe", "be: am, is, are, was, were"], "note": "Main verb + helping verb சேர்ந்து tense உருவாக்கலாம்: is studying, has finished, will go."}, {"name": "Adjective — உரிச்சொல்", "def": "Noun/Pronoun-ஐ விவரிக்கும் சொல்; 'எப்படிப்பட்ட?' என்ற கேள்விக்கு பதில் தரும்.", "ex": ["a beautiful flower", "three books", "an honest person"], "note": "Adjective பொதுவாக noun-க்கு முன் அல்லது linking verb-க்கு பின் வரும்: a tall boy; The boy is tall."}, {"name": "Adverb — வினையடை", "def": "Verb, adjective, மற்ற adverb அல்லது முழு வாக்கியத்தையும் விவரிக்கும்.", "ex": ["She speaks slowly. (verb)", "very good (adjective)", "He runs very quickly. (adverb)"], "note": "எப்படி? எப்போது? எங்கே? எவ்வளவு? போன்ற தகவல்களைத் தரும்: slowly, yesterday, here, very."}, {"name": "Preposition — முன்னிலைச் சொல்", "def": "Noun/Pronoun-ன் இடம், நேரம், திசை அல்லது தொடர்பைக் காட்டும்.", "ex": ["in the room", "on the table", "at 8 o'clock", "from school to home"], "note": "in/on/at போன்றவற்றின் பயன்பாடு context-ஐ பொறுத்தது. Preposition-க்கு பின் noun/pronoun/gerund வரலாம்: interested in learning."}, {"name": "Conjunction — இணைப்புச்சொல்", "def": "சொற்கள், சொற்றொடர்கள் அல்லது clauses-ஐ இணைக்கும் சொல்.", "ex": ["and = மற்றும்", "but = ஆனால்", "because = ஏனெனில்", "although = என்றாலும்", "if = என்றால்"], "note": "Coordinating: and, but, or; subordinating: because, although, if, when; correlative: either...or, neither...nor."}, {"name": "Interjection — உணர்ச்சிக்குறிச்சொல்", "def": "திடீர் உணர்ச்சி/எதிர்வினையை வெளிப்படுத்தும் சொல்.", "ex": ["Wow!", "Oh!", "Oops!", "Hurray!"], "note": "இது sentence-ன் grammatical structure-க்கு அவசியமல்ல; உணர்ச்சியை வெளிப்படுத்துகிறது."}];
const tenses = [{"name": "Simple Present", "use": "வழக்கமான செயல்கள்; பழக்கங்கள்; பொதுவான உண்மைகள்; அட்டவணை/நிர்ணயிக்கப்பட்ட நேரங்கள்; நிரந்தர நிலைகள்", "formula": "Subject + V1 (he/she/it → V1+s/es)", "ex": "I study every day.", "ta": "நான் தினமும் படிக்கிறேன்。", "situations": ["I drink coffee every morning.", "The sun rises in the east.", "The class starts at 8 a.m.", "She lives in Sri Lanka."]}, {"name": "Present Continuous", "use": "இப்போது நடந்து கொண்டிருக்கும் செயல்; இந்த காலகட்டத்தில் தற்காலிகமாக நடக்கும் செயல்; மாறிக்கொண்டிருக்கும் நிலை; எதிர்காலத்திற்கு ஏற்பாடு செய்த திட்டம்", "formula": "Subject + am/is/are + V-ing", "ex": "I am studying now.", "ta": "நான் இப்போது படித்துக்கொண்டிருக்கிறேன்。", "situations": ["I am reading a book now.", "She is staying with her aunt this week.", "Prices are increasing.", "We are meeting the teacher tomorrow."]}, {"name": "Present Perfect", "use": "முடிந்த ஆனால் தற்போதைய விளைவு உள்ள செயல்; வாழ்க்கை அனுபவம்; இப்போதுவரை நடந்த மாற்றம்/சாதனை; கடந்த காலத்தில் தொடங்கி இன்றுவரை உள்ள நிலை (குறிப்பிட்ட முடிந்த நேரம் இல்லாமல்)", "formula": "Subject + have/has + V3", "ex": "I have finished my work.", "ta": "நான் என் வேலையை முடித்துவிட்டேன்。", "situations": ["I have lost my key.", "Have you ever visited Kandy?", "She has improved a lot.", "We have known him for five years."]}, {"name": "Present Perfect Continuous", "use": "கடந்த காலத்தில் தொடங்கி இப்போது வரை தொடரும் செயல்; சமீபத்தில் தொடர்ந்து நடந்ததற்கான விளைவு; செயல் எவ்வளவு நேரமாக நடக்கிறது என்பதில் கவனம்", "formula": "Subject + have/has been + V-ing", "ex": "I have been studying for two hours.", "ta": "நான் இரண்டு மணிநேரமாக படித்துக்கொண்டிருக்கிறேன்。", "situations": ["I have been waiting since 8.", "She has been working all morning.", "It has been raining for hours.", "They have been learning English this month."]}, {"name": "Simple Past", "use": "கடந்த காலத்தில் குறிப்பிட்ட நேரத்தில் முடிந்த செயல்; தொடர்ச்சியான கடந்த நிகழ்வுகள்; கடந்த பழக்கம்; கதை/நிகழ்வுகளை வரிசையாகச் சொல்லுதல்", "formula": "Subject + V2", "ex": "I visited Colombo yesterday.", "ta": "நான் நேற்று கொழும்புக்குச் சென்றேன்。", "situations": ["I watched a movie last night.", "She opened the door and walked in.", "We played outside when we were children.", "He called me two hours ago."]}, {"name": "Past Continuous", "use": "கடந்த காலத்தின் குறிப்பிட்ட நேரத்தில் நடந்துகொண்டிருந்த செயல்; மற்றொரு செயல் நடுவில் குறுக்கிட்ட செயல்; ஒரே நேரத்தில் நடந்த இரண்டு செயல்கள்; பின்னணி விளக்கம்", "formula": "Subject + was/were + V-ing", "ex": "I was studying at 8 p.m.", "ta": "நான் இரவு 8 மணிக்கு படித்துக்கொண்டிருந்தேன்。", "situations": ["I was sleeping when you called.", "They were playing while it was raining.", "She was cooking at 7.", "We were walking home when we saw him."]}, {"name": "Past Perfect", "use": "கடந்த காலத்தில் ஒரு செயல் மற்றொரு கடந்த செயலைவிட முன்பே முடிந்ததை காட்டுதல்; காரணத்தை விளக்குதல்; கடந்த அனுபவத்தின் முன்னுரிமை", "formula": "Subject + had + V3", "ex": "I had finished my work before he came.", "ta": "அவன் வருவதற்கு முன் நான் வேலையை முடித்திருந்தேன்。", "situations": ["She had left before I arrived.", "They had eaten when we reached the restaurant.", "He was tired because he had worked all day.", "I had never seen snow before that trip."]}, {"name": "Past Perfect Continuous", "use": "கடந்த காலத்தில் ஒரு குறிப்பிட்ட நேரம்/நிகழ்வுக்கு முன் நீண்ட நேரம் தொடர்ந்து நடந்த செயல்; கால அளவில் கவனம்; கடந்த நிகழ்வுக்கான காரணத்தை விளக்குதல்", "formula": "Subject + had been + V-ing", "ex": "I had been studying for two hours before dinner.", "ta": "இரவு உணவுக்கு முன் நான் இரண்டு மணிநேரமாக படித்துக்கொண்டிருந்தேன்。", "situations": ["She had been waiting for an hour when the bus arrived.", "They had been working all day, so they were tired.", "It had been raining before we left.", "He had been learning English for a year before he moved."]}, {"name": "Simple Future", "use": "உடனடி முடிவு; எதிர்கால கணிப்பு; வாக்குறுதி/சலுகை; எதிர்கால நிகழ்வு பற்றிய நம்பிக்கை; எதிர்கால உண்மை/செயல்", "formula": "Subject + will + V1", "ex": "I will call you tomorrow.", "ta": "நான் நாளை உன்னை அழைப்பேன்。", "situations": ["I will help you.", "I think it will rain.", "We will visit them next week.", "She will probably pass the exam."]}, {"name": "Future Continuous", "use": "எதிர்கால குறிப்பிட்ட நேரத்தில் நடந்து கொண்டிருக்கும் செயல்; எதிர்கால இயல்பான திட்டம்/நிலை; மரியாதையாக ஒருவரின் திட்டத்தை கேட்பது", "formula": "Subject + will be + V-ing", "ex": "I will be studying at 8 p.m.", "ta": "நான் இரவு 8 மணிக்கு படித்துக்கொண்டிருப்பேன்。", "situations": ["This time tomorrow, I will be travelling.", "She will be working at 10.", "Will you be using the car tonight?", "They will be staying at a hotel next week."]}, {"name": "Future Perfect", "use": "எதிர்கால குறிப்பிட்ட நேரத்திற்கு முன் முடிந்திருக்கும் செயல்; deadline/இலக்கைச் சொல்லுதல்; எதிர்காலத்தில் ஒரு நிலை முடிந்திருக்கும் என்று கணித்தல்", "formula": "Subject + will have + V3", "ex": "I will have finished the work by Friday.", "ta": "வெள்ளிக்குள் நான் வேலையை முடித்திருப்பேன்。", "situations": ["By 8 p.m., she will have arrived.", "They will have completed the project by June.", "By next year, I will have graduated.", "He will have left before you arrive."]}, {"name": "Future Perfect Continuous", "use": "எதிர்கால குறிப்பிட்ட நேரம் வரை தொடர்ந்து நடந்திருக்கும் செயல்; எதிர்கால நேரத்தில் செயலின் கால அளவை வலியுறுத்துதல்", "formula": "Subject + will have been + V-ing", "ex": "By June, I will have been studying English for a year.", "ta": "ஜூன் மாதத்திற்குள் நான் ஒரு வருடமாக ஆங்கிலம் படித்துக்கொண்டிருப்பேன்。", "situations": ["By 6 p.m., I will have been working for eight hours.", "Next month, she will have been living here for five years.", "By noon, they will have been travelling for six hours.", "In July, he will have been teaching for ten years."]}];
