class HomePage extends StatelessWidget {
  const HomePage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('GrammarFlex'),
        centerTitle: true,
        actions: [
          IconButton(
            icon: const Icon(Icons.info_outline),
            onPressed: () => showAboutDialog(
              context: context,
              applicationName: 'GrammarFlex',
              applicationVersion: '1.0.0',
              applicationIcon: Image.asset('assets/grammarflex_logo.png', width: 50),
              children: const [Text('தமிழ் வழி ஆங்கிலம் — Learn • Practice • Grow')],
            ),
          ),
        ],
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          Card(
            elevation: 2,
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: Row(children: [
                Image.asset('assets/grammarflex_logo.png', width: 72, height: 72),
                const SizedBox(width: 16),
                const Expanded(child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('👋 வரவேற்கிறோம்!', style: TextStyle(fontSize: 23, fontWeight: FontWeight.bold)),
                    SizedBox(height: 6),
                    Text('GrammarFlex மூலம் English Grammar-ஐ தமிழில் எளிமையாக கற்றுக்கொள்ளுங்கள்.'),
                  ],
                )),
              ]),
            ),
          ),
          _card(context, '🧩', 'Parts of Speech', '8 வகைகள் • Deep explanation • Examples',
              () => Navigator.push(context, MaterialPageRoute(builder: (_) => const PartsPage()))),
          _card(context, '⏰', '12 Tenses', 'பல பயன்பாட்டு சந்தர்ப்பங்கள் • Formula • Examples',
              () => Navigator.push(context, MaterialPageRoute(builder: (_) => const TensesPage()))),
          _card(context, '📝', 'Irregular Verbs', '${irregular.length} verbs • V1 • V2 • V3 • தமிழ் meaning',
              () => Navigator.push(context, MaterialPageRoute(builder: (_) => const IrregularPage()))),
          _card(context, '📚', 'Vocabulary', '${vocab.length} words • English + தமிழ்',
              () => Navigator.push(context, MaterialPageRoute(builder: (_) => const VocabularyPage()))),
          _card(context, '🎯', 'Grammar Quiz', '${quizBank.length} questions • Score • Feedback',
              () => Navigator.push(context, MaterialPageRoute(builder: (_) => const QuizPage()))),
        ],
      ),
      bottomNavigationBar: const Padding(
        padding: EdgeInsets.all(10),
        child: Text('GrammarFlex 📚 | தமிழ் வழி ஆங்கிலம்', textAlign: TextAlign.center),
      ),
    );
  }

  static Widget _card(BuildContext context, String icon, String title, String sub, VoidCallback tap) {
    return Card(
      margin: const EdgeInsets.only(top: 12),
      child: ListTile(
        contentPadding: const EdgeInsets.all(18),
        leading: CircleAvatar(radius: 28, child: Text(icon, style: const TextStyle(fontSize: 25))),
        title: Text(title, style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
        subtitle: Padding(padding: const EdgeInsets.only(top: 5), child: Text(sub)),
        trailing: const Icon(Icons.arrow_forward_ios, size: 16),
        onTap: tap,
      ),
    );
  }
}

class PartsPage extends StatelessWidget {
  const PartsPage({super.key});
  @override Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Parts of Speech — Deep')),
    body: ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: parts.length,
      itemBuilder: (_, i) {
        final p=parts[i];
        return Card(child: ExpansionTile(
          leading: CircleAvatar(child: Text('${i+1}')),
          title: Text(p['name'], style: const TextStyle(fontWeight: FontWeight.bold)),
          subtitle: Text(p['def']),
          children: [
            ...List<Widget>.from((p['ex'] as List).map((e)=>ListTile(
              leading: const Icon(Icons.check_circle_outline),
              title: Text(e),
            ))),
            Padding(padding: const EdgeInsets.fromLTRB(16,0,16,16), child: Text('🔎 Important: ${p['note']}')),
          ],
        ));
      },
    ),
  );
}

class TensesPage extends StatelessWidget {
  const TensesPage({super.key});
  @override Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('12 Tenses')),
    body: ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: tenses.length,
      itemBuilder: (_, i) {
        final t=tenses[i];
        final uses=(t['use'] as String).split(';');
        return Card(child: ExpansionTile(
          leading: CircleAvatar(child: Text('${i+1}')),
          title: Text(t['name'], style: const TextStyle(fontWeight: FontWeight.bold)),
          children: [
            const ListTile(title: Text('📌 பயன்படுத்தும் சந்தர்ப்பங்கள்', style: TextStyle(fontWeight: FontWeight.bold))),
            ...uses.map((u)=>ListTile(leading: const Icon(Icons.circle, size: 8), title: Text(u.trim()))),
            ListTile(title: Text('Formula: ${t['formula']}', style: const TextStyle(fontWeight: FontWeight.bold))),
            ListTile(title: Text('Example: ${t['ex']}\nதமிழ்: ${t['ta']}')),
            const ListTile(title: Text('🌍 Real-life contexts', style: TextStyle(fontWeight: FontWeight.bold))),
            ...(t['situations'] as List).map((s)=>ListTile(leading: const Icon(Icons.arrow_right), title: Text(s))),
          ],
        ));
      },
    ),
  );
}

class IrregularPage extends StatefulWidget {
  const IrregularPage({super.key});
  @override State<IrregularPage> createState()=>_IrregularPageState();
}
class _IrregularPageState extends State<IrregularPage> {
  String search='';
  @override Widget build(BuildContext context) {
    final list=irregular.where((x)=>x.join(' ').toLowerCase().contains(search.toLowerCase())).toList();
    return Scaffold(
      appBar: AppBar(title: const Text('Irregular Verbs')),
      body: Column(children:[
        Padding(padding: const EdgeInsets.all(12), child: TextField(
          decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText:'Verb / தமிழ் meaning தேடுங்கள்...', border: OutlineInputBorder()),
          onChanged:(v)=>setState(()=>search=v),
        )),
        Padding(padding: const EdgeInsets.symmetric(horizontal:12), child: Align(alignment:Alignment.centerLeft, child: Text('${list.length} / ${irregular.length} verbs'))),
        const SizedBox(height: 6),
        Expanded(child: ListView.builder(
          itemCount:list.length,
          itemBuilder:(_,i){final x=list[i]; return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:4), child: Padding(
            padding:const EdgeInsets.all(12),
            child: Row(children:[
              Expanded(child: Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                Text('V1  ${x[0]}',style:const TextStyle(fontWeight:FontWeight.bold)),
                Text('V2  ${x[1]}'), Text('V3  ${x[2]}'),
              ])),
              Expanded(child: Text(x[3])),
            ]),
          ));}
        )),
      ]),
    );
  }
}

class VocabularyPage extends StatefulWidget {
  const VocabularyPage({super.key});
  @override State<VocabularyPage> createState()=>_VocabularyPageState();
}
class _VocabularyPageState extends State<VocabularyPage> {
  String search='';
  @override Widget build(BuildContext context) {
    final list=vocab.where((x)=>x.join(' ').toLowerCase().contains(search.toLowerCase())).toList();
    return Scaffold(appBar:AppBar(title:const Text('Vocabulary')),
      body:Column(children:[
        Padding(padding:const EdgeInsets.all(12),child:TextField(
          decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'English / தமிழ் meaning...',border:OutlineInputBorder()),
          onChanged:(v)=>setState(()=>search=v),
        )),
        Expanded(child:ListView.builder(itemCount:list.length,itemBuilder:(_,i)=>ListTile(
          leading:CircleAvatar(child:Text('${i+1}')), title:Text(list[i][0],style:const TextStyle(fontWeight:FontWeight.bold)),
          subtitle:Text('${list[i][1]}  •  ${list[i][2]}'),
        ))),
      ]));
  }
}

class QuizPage extends StatefulWidget {
  const QuizPage({super.key});
  @override State<QuizPage> createState()=>_QuizPageState();
}
class _QuizPageState extends State<QuizPage> {
  int index=0, score=0;
  bool locked=false;
  void answer(String a) {
    if(locked) return;
    final q=quizBank[index];
    final ok=a==q['a'];
    setState(() {locked=true; if(ok) score++;});
    Future.delayed(const Duration(milliseconds:700),(){
      if(!mounted)return;
      if(index+1<quizBank.length) setState((){index++;locked=false;});
      else showDialog(context:context,barrierDismissible:false,builder:(_)=>AlertDialog(
        title:const Text('🏆 Quiz முடிந்தது!'),
        content:Text('$score / ${quizBank.length}'),
        actions:[TextButton(onPressed:()=>Navigator.popUntil(context,(r)=>r.isFirst),child:const Text('Home'))],
      ));
    });
  }
  @override Widget build(BuildContext context) {
    final q=quizBank[index];
    return Scaffold(appBar:AppBar(title:const Text('Grammar Quiz')),body:Padding(
      padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
        LinearProgressIndicator(value:(index+1)/quizBank.length),
        const SizedBox(height:12),
        Text('Question ${index+1} / ${quizBank.length}   •   Score: $score'),
        const SizedBox(height:18),
        Text(q['q'],style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),
        const SizedBox(height:15),
        ...(q['o'] as List).map((o)=>Padding(padding:const EdgeInsets.only(bottom:10),child:SizedBox(
          width:double.infinity,child:OutlinedButton(
            onPressed:locked?null:()=>answer(o),
            child:Padding(padding:const EdgeInsets.all(12),child:Text(o,style:const TextStyle(fontSize:16))),
          )))),
      ]));
  }
}
